import * as puppeteer from "puppeteer";

import { Locale } from "./types/locales";
import { normalizer } from "./normalizer";

const GOOGLE_TRANSLATE_CHARACTER_LIMIT = 5000;

export interface Translate {
	from?: Locale;
	to: Locale;
}

export type Texts = string | string[] | Object;

function breakText(text: string, limit: number): string[] {
	text = text.trim();
	const regex = new RegExp(`(.{1,${limit}}(\\s|$))`, "gm");
	const matchResult = text.match(regex);
	if (!matchResult) {
		return [];
	}
	return matchResult.map(t => t.trim());
}

async function google_translate(
	page: puppeteer.Page,
	txt: string,
): Promise<string> {
	// Handle empty or whitespace-only strings
	if (!txt || txt.trim() === "") {
		return "";
	}

	// Clear the input area and set new text
	await page.evaluate(text => {
		console.log("translating", text);
		
		// Find and clear the textarea
		let el = document.querySelector(
			'textarea[jsname="BJE2fc"]',
		) as HTMLTextAreaElement;
		
		if (!el) {
			throw new Error("Translation textarea not found");
		}
		
		// Clear previous content completely
		el.focus();
		el.select(); // Select all existing text
		el.value = ""; // Clear the value
		
		// Dispatch events to ensure clearing is registered
		el.dispatchEvent(new Event("input", { bubbles: true }));
		el.dispatchEvent(new Event("change", { bubbles: true }));
		
		// Wait a moment for the UI to update
		return new Promise(resolve => setTimeout(resolve, 100));
	}, txt);
	
	// Add small delay to ensure clearing is processed
	await new Promise(resolve => setTimeout(resolve, 500));
	
	// Now set the new text
	await page.evaluate(text => {
		let el = document.querySelector(
			'textarea[jsname="BJE2fc"]',
		) as HTMLTextAreaElement;
		
		el.focus();
		el.value = text as string;
		
		// Dispatch multiple events to ensure Google Translate recognizes the input
		el.dispatchEvent(new Event("input", { bubbles: true }));
		el.dispatchEvent(new Event("change", { bubbles: true }));
		el.dispatchEvent(new KeyboardEvent("keyup", { bubbles: true }));
	}, txt);
	
	// Wait for translation to be processed
	await page.waitForResponse(response =>
		response.url().includes("_/TranslateWebserverUi")
	);
	
	// Wait for additional processing
	await page.waitForResponse(response =>
		response.url().includes("/log?format=json")
	);
	
	// Add delay to ensure translation is complete
	await new Promise(resolve => setTimeout(resolve, 500));
	
	// Wait for the translation result to appear and get the text
	await page.waitForSelector("span[jsname=jqKxS]", { timeout: 10000 });
	
	// Get the translated text
	const translatedText = await page.evaluate(() => {
		let el = document.querySelector("span[jsname=jqKxS]") as HTMLElement;
		if (!el) {
			throw new Error("Translation result element not found");
		}
		return el.innerText || el.textContent || "";
	});
	
	if (!translatedText.trim()) {
		throw new Error("Empty translation result received");
	}
	
	return translatedText.trim();
}

interface TranslatorParams {
	from: string;
	to: string;
	text: Texts;
}

async function translator({
	from,
	to,
	text,
}: TranslatorParams): Promise<string | string[] | Object> {
	let browser: puppeteer.Browser | null = null;
	try {
		// Handle empty inputs early
		if (typeof text === "string" && text.trim() === "") {
			return "";
		}
		if (Array.isArray(text) && text.length === 0) {
			return [];
		}
		if (typeof text === "object" && !Array.isArray(text) && Object.keys(text).length === 0) {
			return {};
		}

		browser = await puppeteer.launch({
			timeout: 60000,
			headless: "new",
			// headless: false,
		});
		const textType = typeof text;
		let texts = {};
		let translatedTexts = {};

		// if "text" is string, convert it to object
		// if text is array, convert it to object
		// if text is object, do nothing
		if (typeof text === "string") {
			texts = { ...[text] };
		} else if (Array.isArray(text)) {
			texts = { ...text };
		} else {
			texts = text;
		}

		const page = await browser.newPage();
		const url = `https://translate.google.com/?sl=${from}&tl=${to}&op=translate`;

		// open page and wait for it to load
		await page.goto(url).then(() => page.waitForSelector("textarea"));

		// for each text, translate it and add it to the translatedTexts array
		for (let key in texts) {
			const txt = texts[key];
			
			// Handle empty strings in arrays/objects
			if (!txt || txt.trim() === "") {
				translatedTexts[key] = "";
				continue;
			}
			
			if (txt.length > GOOGLE_TRANSLATE_CHARACTER_LIMIT) {
				const textArray = breakText(
					txt,
					GOOGLE_TRANSLATE_CHARACTER_LIMIT,
				);
				let combinedTranslation = "";
				for (const text of textArray) {
					const translation = await google_translate(page, text);
					combinedTranslation += translation + " ";
				}
				translatedTexts[key] = combinedTranslation.trim();
			} else {
				translatedTexts[key] = await google_translate(page, txt);
			}
		}

		if (!Object.keys(translatedTexts).length) {
			// if no text was translated, throw an error
			return Promise.reject(
				Error(
					"No text was translated, try again, " +
						JSON.stringify(translatedTexts),
				),
			);
		}

		return textType === "string"
			? translatedTexts[0]
			: Array.isArray(text)
			? Object.values(translatedTexts)
			: translatedTexts;
	} catch (error) {
		throw error;
	} finally {
		// Ensure browser is always closed
		if (browser) {
			await browser.close();
		}
	}
}

export async function translate(
	text: Texts,
	languages: Translate,
): Promise<string | string[] | Object> {
	const from = normalizer(languages?.from || "auto");
	const to = normalizer(languages.to);

	if (from === to) {
		console.log("from and to are the same!, returning text");
		return text;
	}

	return await translator({
		from: from,
		to: to,
		text: text,
	});
}
